using System.Windows;using LabMaster.Services;using LabMaster.Models;namespace LabMaster;public partial class EditTestWindow:Window{readonly TestMasterService service=new();readonly TestMasterItem test;public EditTestWindow(TestMasterItem t){InitializeComponent();test=t;CodeBox.Text=t.TestCode;NameBox.Text=t.TestName;SampleBox.Text=t.SampleType;UnitBox.Text=t.Unit;RangeBox.Text=t.ReferenceRange;PriceBox.Text=t.Price.ToString("0.00");Loaded+=async(_,_)=>{DepartmentBox.ItemsSource=await service.GetDepartmentsAsync();DepartmentBox.SelectedItem=((System.Collections.IEnumerable)DepartmentBox.ItemsSource).Cast<DepartmentOption>().FirstOrDefault(x=>x.Id==test.DepartmentId);};}async void Save_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(CodeBox.Text)||string.IsNullOrWhiteSpace(NameBox.Text)||DepartmentBox.SelectedItem is not DepartmentOption d||!decimal.TryParse(PriceBox.Text,out var price)){Status.Text="Code, name, department and valid price are required.";return;}try{await service.UpdateAsync(test.TestId,CodeBox.Text,NameBox.Text,d.Id,SampleBox.Text,UnitBox.Text,RangeBox.Text,price);DialogResult=true;}catch(Exception ex){Status.Text=ex.Message;}}}